package com.bank.filter;

import java.util.*;
import java.util.logging.*;

public class PredicateAndDemo {
    private static final Logger log = Logger.getLogger("Filter");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),
            new Employee("Amit", "IT", 40000),      // IT but low salary
            new Employee("Priya", "Sales", 250000), // high salary but not IT
            new Employee("Karan", "IT", 80000));
        EmployeeFilterService service = new EmployeeFilterService();

        List<String> result = service.highPaidIT(staff);
        log.info(() -> "High-paid IT staff: " + result);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
            this.name = name;
            this.department = department
            this.salary = salary;
    }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/EmployeeFilterService.java ───
class EmployeeFilterService {
    // reusable named predicates
    private final java.util.function.Predicate<Employee> highSalary =
        e -> e.getSalary() > 50_000;
    private final java.util.function.Predicate<Employee> inIT =
        e -> "IT".equals(e.getDepartment());

    List<String> highPaidIT(List<Employee> staff) {
        return staff.stream()
            .filter(highSalary.and(inIT))     // BOTH must be true
            .map(Employee::getName)
            .toList();
    }
}
